using AutoMapper;
using EmployeeService.DTOs.Employee;
using EmployeeService.Models;

namespace EmployeeService.Mappings;

public class EmployeeProfile : Profile
{
    public EmployeeProfile()
    {
        // Read side: also used with ProjectTo, so it is translated to a single SQL query.
        // DepartmentName is flattened from Department.Name; Addresses uses AddressProfile.
        CreateMap<Employee, EmployeeListDto>();

        // Write side: EmployeeNumber is generated by the service, Id / audit fields by the DbContext.
        CreateMap<EmployeeCreateDto, Employee>()
            .ForMember(d => d.Id, o => o.Ignore())
            .ForMember(d => d.CreatedAt, o => o.Ignore())
            .ForMember(d => d.UpdatedAt, o => o.Ignore())
            .ForMember(d => d.EmployeeNumber, o => o.Ignore())
            .ForMember(d => d.Department, o => o.Ignore())
            .ForMember(d => d.IdentityNumber, o => o.MapFrom(s => s.IdentityNumber.Trim()))
            .ForMember(d => d.FirstName, o => o.MapFrom(s => s.FirstName.Trim()))
            .ForMember(d => d.LastName, o => o.MapFrom(s => s.LastName.Trim()))
            .ForMember(d => d.Email, o => o.MapFrom(s => s.Email.Trim()))
            .ForMember(d => d.PhoneNumber, o => o.MapFrom(s => NormalizePhone(s.PhoneNumber)))
            .ForMember(d => d.JobTitle, o => o.MapFrom(s =>
                string.IsNullOrWhiteSpace(s.JobTitle) ? null : s.JobTitle.Trim()));

        // Scalar fields only; addresses are synced separately by the service.
        CreateMap<EmployeeUpdateDto, Employee>()
            .ForMember(d => d.Id, o => o.Ignore())
            .ForMember(d => d.CreatedAt, o => o.Ignore())
            .ForMember(d => d.UpdatedAt, o => o.Ignore())
            .ForMember(d => d.EmployeeNumber, o => o.Ignore())
            .ForMember(d => d.Department, o => o.Ignore())
            .ForMember(d => d.Addresses, o => o.Ignore())
            .ForMember(d => d.IdentityNumber, o => o.MapFrom(s => s.IdentityNumber.Trim()))
            .ForMember(d => d.FirstName, o => o.MapFrom(s => s.FirstName.Trim()))
            .ForMember(d => d.LastName, o => o.MapFrom(s => s.LastName.Trim()))
            .ForMember(d => d.Email, o => o.MapFrom(s => s.Email.Trim()))
            .ForMember(d => d.PhoneNumber, o => o.MapFrom(s => NormalizePhone(s.PhoneNumber)))
            .ForMember(d => d.JobTitle, o => o.MapFrom(s =>
                string.IsNullOrWhiteSpace(s.JobTitle) ? null : s.JobTitle.Trim()));
    }

    /// <summary>
    /// Accepts 5xxxxxxxxx and 05xxxxxxxxx, stores 05xxxxxxxxx.
    /// </summary>
    private static string? NormalizePhone(string? phone)
    {
        if (string.IsNullOrWhiteSpace(phone))
        {
            return null;
        }

        var digits = new string(phone.Where(char.IsDigit).ToArray());
        if (digits.Length == 10)
        {
            digits = "0" + digits;
        }

        return digits.Length == 0 ? null : digits;
    }
}
